HERO_STR_STATIC(hero_str_6700e3ab, "C keeps struct tags in a namespace of their own: say which tag with `tag`, and the Heroes name stays yours \342\200\224 `record FileStat tag stat` binds `struct stat` beside the `function stat` that fills it");
HERO_STR_STATIC(hero_str_d0b65f, "name the header's tag: `tag ");
