HERO_STR_STATIC(hero_str_65aa7107, "ffi_unknown_tag");
HERO_STR_STATIC(hero_str_4d00cb56, "`struct ");
HERO_STR_STATIC(hero_str_70e2e74b, "` has no fields in `");
HERO_STR_STATIC(hero_str_4345c5d4, "` \342\200\224 clang read the header and cannot lay the type out");
HERO_STR_STATIC(hero_str_5254ac1b, "two things give clang that answer and it reports them alike, so both repairs are here. The tag may be MISSPELLED, in which case C has invented an empty type of that name: correct it, or name the header that declares it. Or the type may be OPAQUE on purpose \342\200\224 `typedef struct sqlite3 sqlite3;` and nothing more \342\200\224 in which case the header never means for a program to hold one by value, and what is wanted is a HANDLE: drop the field block and the `record` becomes C's pointer to it, `record Db tag ");
HERO_STR_STATIC(hero_str_8d4bb5f, "` (\302\247 13)");
HERO_STR_STATIC(hero_str_1016e4fc, "with tag type that does not match previous declaration");
HERO_STR_STATIC(hero_str_4501e82a, "not a tag-mismatch line");
HERO_STR_STATIC(hero_str_3bca4ff5, "use of '");
HERO_STR_STATIC(hero_str_4ec57cab, "no tag on the line");
HERO_STR_STATIC(hero_str_edaf109, "ffi_tag_is_a_union");
HERO_STR_STATIC(hero_str_19e50894, "` as a `union`, not a struct \342\200\224 C keeps the two in one namespace and will not let one stand for the other");
HERO_STR_STATIC(hero_str_51d3ecfd, "a group's `record` is the header's STRUCT (\302\2474.19). A union has no `record` spelling in this language: reach it as a `ptr` and read it through C functions, or bind the one member you need as its own type");
